// src/components/pages/Landing.jsx
import React from "react";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import PageWrapper from "../PageWrapper";

const Landing = () => {
  const navigate = useNavigate();

  return (
    <PageWrapper>
      <div className="flex justify-center items-center min-h-screen bg-gray-900 px-6">
        <motion.div
          initial={{ opacity: 0, y: 50 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="bg-gray-800 rounded-2xl shadow-2xl p-10 max-w-lg w-full text-center"
        >
          {/* Heading */}
          <motion.h1
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, delay: 0.2 }}
            className="text-4xl md:text-5xl font-extrabold text-white mb-4"
            style={{ fontFamily: "'Poppins', 'Inter', sans-serif" }}
          >
            Welcome to <span className="text-indigo-500">AI Interview Coach</span>
          </motion.h1>

          {/* Subheading */}
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.8, delay: 0.4 }}
            className="text-gray-300 text-lg mb-8"
          >
            Get personalized, AI-powered feedback to boost your confidence and improve your interview performance.
          </motion.p>

          {/* Start Learning Button */}
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={() => navigate("/login")}
            className="bg-black hover:bg-gray-900 text-white font-semibold text-lg px-10 py-4 rounded-full shadow-lg transition-all duration-300"
          >
            Start Learning 🚀
          </motion.button>

          {/* Optional small link to login */}
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.8, delay: 0.6 }}
            className="mt-6 text-gray-400 text-sm"
          >
            Already have an account?{" "}
            <span
              className="text-indigo-500 cursor-pointer hover:underline"
              onClick={() => navigate("/login")}
            >
              Login
            </span>
          </motion.p>
        </motion.div>
      </div>
    </PageWrapper>
  );
};

export default Landing;
